 const pair=selectedPair();if(!pair){state.pair='';writeURL('replace');el('p',state.pairFilter==='controls'?'This run has no seeded control pairs. Choose All Pairs to inspect the available comparisons.':'Every pair in this queue has an answer. Choose All Pairs to revisit earlier decisions.',top);button('Review All Pairs',top,()=>navigate({pairFilter:'all',pair:'',reveal:false,pairAudio:'',pairTime:0,scroll:0}));pairScoreboard(review);return;}state.pair=pair.id;writeURL('replace');const truth=S.pairTruth(feedback,pair,data.results.pair_review?.sample_passages||{}),queue=pairQueue(),index=queue.findIndex(item=>item.id===pair.id);
 const nav=bar;const previous=button('Previous Pair',nav,()=>goPair(-1));previous.disabled=!S.neighborPair(review,feedback,state,-1);el('span',index>=0?`Pair ${index+1} in this queue`:truth.verdict?'This pair already has an answer':'This pair is outside the selected queue',nav);const next=button('Next Pair',nav,()=>goPair(1));next.disabled=!S.neighborPair(review,feedback,state,1);
