 const edits=el('div',undefined,decisions,'toolbar');button('Save Names',edits,()=>{const updated=S.namePair(feedback,pair,nameValues);for(const id of pair.sample_ids)delete formDrafts['pair-person:'+id];if(updated)changed();else draft();render();});const clear=button('Clear Direct Answer',edits,()=>answerPair(''));clear.disabled=!truth.explicit;const undo=button('Undo Review Change',edits,()=>{const op=S.undoPair(feedback);if(op){if(op.kind==='pair-names')for(const id of Object.keys(op.previous))delete formDrafts['pair-person:'+id];changed();navigate({pair:op.pair,reveal:false,scroll:0});}});undo.disabled=!feedback.pairHistory.length;
