 const pane=el('div',undefined,workspace,'transcript-pane'),m=meeting(state.meeting),head=el('div',undefined,pane,'transcript-head');el('h2',m?.title||'Meeting',head);el('p',`${date(m?.createdAt)} · ${time(m?.duration||0)} · Transcript review`,head,'muted');
 const bar=el('div',undefined,head,'toolbar transcript-filters');modelControls(bar);select('Show passages',[['all','All passages'],['unreviewed','Unreviewed'],['wrong','Wrong identity'],['unsure','Unsure'],['correct','Correct'],['skip','Skipped']],state.rowFilter,v=>navigate({rowFilter:v,page:0,row:'',transcriptScroll:0,scroll:0}),bar);
 const followLabel=el('label',undefined,bar,'check-label'),follow=el('input',undefined,followLabel);follow.type='checkbox';follow.checked=state.follow;followLabel.append(document.createTextNode('Follow Playback'));follow.onchange=()=>{state.follow=follow.checked;writeURL('replace');updateTranscriptPlayer();};
 const progress=el('span','',bar,'muted');progress.id='transcript-progress';const help=el('details',undefined,head,'transcript-help');el('summary','Help',help);help.open=state.open.includes('transcript-help');
 const definitions=el('dl',undefined,help);for(const [term,meaning] of [['Unclustered','An embedding exists, but this setting assigned it to no group.'],['Excluded: window overlap','This audio window overlaps another window used for clustering. It was excluded to avoid counting the same audio twice.'],['No voice evidence','No embedding covers this interval. It may contain silence or missed speech.'],['Partial','Voice evidence covers only part of the passage. The blocks show which intervals.'],['Playback and corrections','Click text to play the passage; click a block to play and correct that interval. The right column judges the whole passage.'],['Interval corrections','Person, Unclear, and Multiple Voices apply across methods. Wrong Group judges only the selected method.'],['Shortcuts','Space: play/pause · ↑/↓: passages · 1/2/3/4: correct/wrong/unsure/skip']]){el('dt',term,definitions);el('dd',meaning,definitions);}help.ontoggle=()=>{if(!help.isConnected)return;state.open=help.open?[...new Set([...state.open,'transcript-help'])]:state.open.filter(key=>key!=='transcript-help');writeURL('replace');};
