async function bootstrap(){document.querySelector('#loading').textContent='Loading the experiment…';return Promise.all([fetch('/data.json').then(r=>{if(!r.ok)throw Error('Experiment data unavailable');return r.json();}),fetch('/feedback.json').then(r=>r.json())]).then(([d,f])=>{data=d;visibleMethods=S.selectedMethods(data.results);for(const entry of S.catalog(data.results))names[entry.id]=entry.label||entry.short_label||pretty(entry.id);if(!visibleMethods.length)throw Error('The comparison has no supported methods.');state=S.reconcileMethod(state,visibleMethods);feedback=S.ensureFeedback(f);draftKey='voice-review-draft:'+data.dataset;let stored;try{stored=JSON.parse(localStorage.getItem(draftKey)||'null');}catch{}if(stored?.dataset===data.dataset){if(stored.baseRevision===feedback.revision){feedback=S.ensureFeedback(stored.feedback);formDrafts=stored.formDrafts||{};dirty=Boolean(stored.dirty);if(dirty)status.textContent='Restored browser draft · Select Save Feedback to keep it in the experiment';}else if(stored.dirty||Object.keys(stored.formDrafts||{}).length){recoveredDraft=[stored];try{localStorage.setItem(draftKey+':recovered:'+stored.updatedAt,JSON.stringify(stored));}catch{}}}
 try{const archived=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith(draftKey+':recovered:')){const entry=JSON.parse(localStorage.getItem(key));if(entry)archived.push(entry);}}if(archived.length)recoveredDraft=[...(recoveredDraft||[]),...archived];}catch{}

 if(!state.meeting||!data.meetings.some(m=>m.id===state.meeting))state.meeting=[...data.meetings].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0))[0]?.id||'';document.querySelector('#loading').hidden=true;document.querySelector('#save').disabled=false;document.querySelector('#export').disabled=false;writeURL('replace');render();}).catch(error=>{const loading=document.querySelector('#loading')||el('div',undefined,view);loading.replaceChildren();el('p',`Could not load the experiment: ${error.message}`,loading);button('Retry',loading,bootstrap);});}
